using namespace std;

string pattern, s;
map<char, string> mapping;
set<string> used;  // strings already taken by some letter

bool visit(size_t i, size_t j) {
    if (i == pattern.size()) return j == s.size();
    if (s.size() - j < pattern.size() - i) return false;
    char c = pattern[i];
    auto it = mapping.find(c);
    if (it != mapping.end()) {
        const string &word = it->second;
        return s.compare(j, word.size(), word) == 0 && visit(i + 1, j + word.size());
    }
    // try every non-empty prefix that leaves at least one letter per remaining pattern char
    for (size_t end = j + 1; end <= s.size() - (pattern.size() - i - 1); end++) {
        string word = s.substr(j, end - j);
        if (used.count(word)) continue;
        mapping[c] = word;
        used.insert(word);
        if (visit(i + 1, end)) return true;
        used.erase(word);
        mapping.erase(c);
    }
    return false;
}

