import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    static String pattern, s;
    static Map<Character, String> mapping = new HashMap<>();
    static Set<String> used = new HashSet<>(); // strings already taken by some letter

    static boolean visit(int i, int j) {
        if (i == pattern.length()) return j == s.length();
        if (s.length() - j < pattern.length() - i) return false;
        char c = pattern.charAt(i);
        String word = mapping.get(c);
        if (word != null) return s.startsWith(word, j) && visit(i + 1, j + word.length());
        // try every non-empty prefix that leaves at least one letter per remaining pattern char
        for (int end = j + 1; end <= s.length() - (pattern.length() - i - 1); end++) {
            String candidate = s.substring(j, end);
            if (used.contains(candidate)) continue;
            mapping.put(c, candidate);
            used.add(candidate);
            if (visit(i + 1, end)) return true;
            used.remove(candidate);
            mapping.remove(c);
        }
        return false;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        pattern = next();
        s = next();
        System.out.println(visit(0, 0) ? 1 : 0);
