var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

var pattern, s string
var mapping = map[byte]string{}
var used = map[string]bool{} // strings already taken by some letter

func visit(i, j int) bool {
	if i == len(pattern) {
		return j == len(s)
	}
	if len(s)-j < len(pattern)-i {
		return false
	}
	c := pattern[i]
	if word, ok := mapping[c]; ok {
		return strings.HasPrefix(s[j:], word) && visit(i+1, j+len(word))
	}
	// try every non-empty prefix that leaves at least one letter per remaining pattern char
	for end := j + 1; end <= len(s)-(len(pattern)-i-1); end++ {
		word := s[j:end]
		if used[word] {
			continue
		}
		mapping[c] = word
		used[word] = true
		if visit(i+1, end) {
			return true
		}
		delete(used, word)
		delete(mapping, c)
	}
	return false
}

